import { createServer } from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_PATH = join(__dirname, "data", "books.json");
const PUBLIC_DIR = join(__dirname, "public");
const PORT = Number(process.env.PORT) || 3000;

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export async function loadBooks() {
  try {
    const raw = await readFile(DATA_PATH, "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

export async function saveBooks(books) {
  await mkdir(dirname(DATA_PATH), { recursive: true });
  await writeFile(DATA_PATH, JSON.stringify(books, null, 2) + "\n", "utf8");
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <header>
    <a class="brand" href="/">Reading list</a>
  </header>
  <main>${body}</main>
</body>
</html>`;
}

function bookCard(book) {
  const title = escapeHtml(book.title);
  const author = escapeHtml(book.author);
  return `<li class="book-card">
    <a href="/books/${encodeURIComponent(book.id)}">
      <strong>${title}</strong>
      <span>${author}</span>
    </a>
    ${
      book.status === "reading"
        ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
            <button type="submit">Mark finished</button>
          </form>`
        : ""
    }
  </li>`;
}

function listSection(heading, books) {
  if (books.length === 0) {
    return `<section><h2>${heading}</h2><p class="empty">None yet.</p></section>`;
  }
  return `<section><h2>${heading}</h2><ul class="book-list">${books.map(bookCard).join("")}</ul></section>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  return layout(
    "Reading list",
    `<div class="page-head">
      <h1>Reading list</h1>
      <a class="button" href="/books/new">Add a book</a>
    </div>
    ${listSection("Currently reading", reading)}
    ${listSection("Finished", finished)}`
  );
}

function newBookPage(error) {
  return layout(
    "Add a book",
    `<h1>Add a book</h1>
    ${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
    <form method="post" action="/books" class="book-form">
      <label>Title <input name="title" required></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" rows="5"></textarea></label>
      <button type="submit">Add book</button>
    </form>`
  );
}

function bookPage(book) {
  const notes = book.notes?.trim()
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : `<p class="empty">No notes yet.</p>`;
  const finish =
    book.status === "reading"
      ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
          <button type="submit">Mark finished</button>
        </form>`
      : `<p class="status">Finished</p>`;
  return layout(
    book.title,
    `<p class="back"><a href="/">← All books</a></p>
    <h1>${escapeHtml(book.title)}</h1>
    <p class="author">${escapeHtml(book.author)}</p>
    ${finish}
    <h2>Notes</h2>
    ${notes}`
  );
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

function parseForm(raw) {
  const params = new URLSearchParams(raw);
  return {
    title: (params.get("title") || "").trim(),
    author: (params.get("author") || "").trim(),
    notes: (params.get("notes") || "").trim(),
  };
}

const MIME = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
};

function send(res, status, body, type = "text/html; charset=utf-8") {
  res.writeHead(status, { "Content-Type": type });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export async function handleRequest(req, res) {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;
  const method = req.method || "GET";

  if (method === "GET" && path === "/") {
    send(res, 200, homePage(await loadBooks()));
    return;
  }

  if (method === "GET" && path === "/books/new") {
    send(res, 200, newBookPage());
    return;
  }

  if (method === "POST" && path === "/books") {
    const form = parseForm(await readBody(req));
    if (!form.title || !form.author) {
      send(res, 400, newBookPage("Title and author are required."));
      return;
    }
    const books = await loadBooks();
    const book = {
      id: randomUUID(),
      title: form.title,
      author: form.author,
      notes: form.notes,
      status: "reading",
      addedAt: new Date().toISOString(),
    };
    books.push(book);
    await saveBooks(books);
    redirect(res, `/books/${book.id}`);
    return;
  }

  const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
  if (method === "POST" && finishMatch) {
    const id = decodeURIComponent(finishMatch[1]);
    const books = await loadBooks();
    const book = books.find((b) => b.id === id);
    if (!book) {
      send(res, 404, layout("Not found", "<h1>Book not found</h1><p><a href=\"/\">Back</a></p>"));
      return;
    }
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
    redirect(res, `/books/${book.id}`);
    return;
  }

  const bookMatch = path.match(/^\/books\/([^/]+)$/);
  if (method === "GET" && bookMatch) {
    const id = decodeURIComponent(bookMatch[1]);
    const book = (await loadBooks()).find((b) => b.id === id);
    if (!book) {
      send(res, 404, layout("Not found", "<h1>Book not found</h1><p><a href=\"/\">Back</a></p>"));
      return;
    }
    send(res, 200, bookPage(book));
    return;
  }

  if (method === "GET" && path === "/style.css") {
    try {
      const css = await readFile(join(PUBLIC_DIR, "style.css"));
      send(res, 200, css, MIME[".css"]);
    } catch {
      send(res, 404, "Not found", "text/plain; charset=utf-8");
    }
    return;
  }

  send(res, 404, layout("Not found", "<h1>Not found</h1><p><a href=\"/\">Back</a></p>"));
}

const server = createServer((req, res) => {
  handleRequest(req, res).catch((err) => {
    console.error(err);
    if (!res.headersSent) send(res, 500, "Something went wrong.", "text/plain; charset=utf-8");
    else res.end();
  });
});

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  server.listen(PORT, () => {
    console.log(`Reading list at http://localhost:${PORT}`);
  });
}

:root {
  color-scheme: light;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #e7e5e4;
  --paper: #fafaf9;
  --accent: #1d4ed8;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font: 16px/1.5 Georgia, "Times New Roman", serif;
  color: var(--ink);
  background: var(--paper);
}

header, main {
  max-width: 40rem;
  margin: 0 auto;
  padding: 1.25rem 1.25rem 0;
}

main { padding-bottom: 3rem; }

a { color: var(--accent); }

.brand {
  font-weight: 700;
  text-decoration: none;
  color: var(--ink);
}

h1 { font-size: 1.75rem; margin: 0 0 0.5rem; }
h2 { font-size: 1.1rem; margin: 1.75rem 0 0.5rem; }

.page-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.book-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-top: 1px solid var(--line);
  padding: 0.75rem 0;
}

.book-card a {
  text-decoration: none;
  color: inherit;
  display: flex;
  flex-direction: column;
}

.book-card span,
.author,
.empty,
.back {
  color: var(--muted);
}

.notes { white-space: pre-wrap; }

.book-form {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  max-width: 28rem;
}

label { display: flex; flex-direction: column; gap: 0.25rem; }

input, textarea, button, .button {
  font: inherit;
}

input, textarea {
  padding: 0.45rem 0.55rem;
  border: 1px solid #d6d3d1;
  background: white;
}

button, .button {
  display: inline-block;
  width: fit-content;
  padding: 0.4rem 0.75rem;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: white;
  text-decoration: none;
  cursor: pointer;
}

.error { color: #b91c1c; }

.status { color: var(--muted); font-style: italic; }

import { mkdtemp, readFile, rm, writeFile, mkdir } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawn } from "node:child_process";
import { afterEach, describe, expect, it } from "vitest";

const children = [];

function startServer(dataDir, port) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ["server.js"], {
      cwd: process.cwd(),
      env: { ...process.env, PORT: String(port) },
      stdio: ["ignore", "pipe", "pipe"],
    });
    children.push(child);
    let settled = false;
    const timer = setTimeout(() => {
      if (!settled) reject(new Error("server did not start"));
    }, 5000);
    child.stdout.on("data", (buf) => {
      if (buf.toString().includes("Reading list")) {
        settled = true;
        clearTimeout(timer);
        resolve(child);
      }
    });
    child.on("error", reject);
  });
}

afterEach(async () => {
  for (const child of children.splice(0)) {
    child.kill();
  }
});

describe("reading list", () => {
  it("adds a book, shows it as reading, marks it finished, and keeps a shareable page", async () => {
    const port = 3456 + Math.floor(Math.random() * 1000);
    const dataPath = join(process.cwd(), "data", "books.json");
    const original = await readFile(dataPath, "utf8").catch(() => "[]\n");
    await mkdir(join(process.cwd(), "data"), { recursive: true });
    await writeFile(dataPath, "[]\n");

    try {
      await startServer(null, port);
      const base = `http://127.0.0.1:${port}`;

      const home = await fetch(base + "/");
      expect(home.status).toBe(200);
      const homeHtml = await home.text();
      expect(homeHtml).toContain("Currently reading");
      expect(homeHtml).toContain("Finished");

      const form = new URLSearchParams({
        title: "The Left Hand of Darkness",
        author: "Ursula K. Le Guin",
        notes: "Winter and gender.",
      });
      const created = await fetch(base + "/books", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: form,
        redirect: "manual",
      });
      expect(created.status).toBe(303);
      const location = created.headers.get("location");
      expect(location).toMatch(/^\/books\/[^/]+$/);

      const page = await fetch(base + location);
      const pageHtml = await page.text();
      expect(pageHtml).toContain("The Left Hand of Darkness");
      expect(pageHtml).toContain("Ursula K. Le Guin");
      expect(pageHtml).toContain("Winter and gender.");

      const afterAdd = await fetch(base + "/");
      const afterAddHtml = await afterAdd.text();
      expect(afterAddHtml).toContain("The Left Hand of Darkness");

      const finished = await fetch(base + location + "/finish", {
        method: "POST",
        redirect: "manual",
      });
      expect(finished.status).toBe(303);

      const stored = JSON.parse(await readFile(dataPath, "utf8"));
      expect(stored).toHaveLength(1);
      expect(stored[0].status).toBe("finished");
      expect(stored[0].title).toBe("The Left Hand of Darkness");
    } finally {
      await writeFile(dataPath, original);
    }
  });
});

