            <button type="submit">Mark finished</button>
          </form>`
        : ""
    }
  </li>`;
}

function listSection(heading, books) {
  if (books.length === 0) {
    return `<section><h2>${heading}</h2><p class="empty">None yet.</p></section>`;
  }
  return `<section><h2>${heading}</h2><ul class="book-list">${books.map(bookCard).join("")}</ul></section>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");
  return layout(
    "Reading list",
    `<div class="page-head">
      <h1>Reading list</h1>
      <a class="button" href="/books/new">Add a book</a>
    </div>
    ${listSection("Currently reading", reading)}
    ${listSection("Finished", finished)}`
  );
}

function newBookPage(error) {
  return layout(
    "Add a book",
    `<h1>Add a book</h1>
    ${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
    <form method="post" action="/books" class="book-form">
      <label>Title <input name="title" required></label>
      <label>Author <input name="author" required></label>
      <label>Notes <textarea name="notes" rows="5"></textarea></label>
      <button type="submit">Add book</button>
    </form>`
  );
}

function bookPage(book) {
  const notes = book.notes?.trim()
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : `<p class="empty">No notes yet.</p>`;
  const finish =
    book.status === "reading"
      ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
          <button type="submit">Mark finished</button>
        </form>`
      : `<p class="status">Finished</p>`;
  return layout(
    book.title,
    `<p class="back"><a href="/">← All books</a></p>
    <h1>${escapeHtml(book.title)}</h1>
    <p class="author">${escapeHtml(book.author)}</p>
    ${finish}
    <h2>Notes</h2>
    ${notes}`
  );
}

async function readBody(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

function parseForm(raw) {
  const params = new URLSearchParams(raw);
  return {
    title: (params.get("title") || "").trim(),
    author: (params.get("author") || "").trim(),
    notes: (params.get("notes") || "").trim(),
  };
}

const MIME = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
};

function send(res, status, body, type = "text/html; charset=utf-8") {
  res.writeHead(status, { "Content-Type": type });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export async function handleRequest(req, res) {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const path = url.pathname;
  const method = req.method || "GET";

  if (method === "GET" && path === "/") {
    send(res, 200, homePage(await loadBooks()));
    return;
  }

  if (method === "GET" && path === "/books/new") {
    send(res, 200, newBookPage());
    return;
  }

  if (method === "POST" && path === "/books") {
    const form = parseForm(await readBody(req));
    if (!form.title || !form.author) {
      send(res, 400, newBookPage("Title and author are required."));
      return;
    }
    const books = await loadBooks();
    const book = {
      id: randomUUID(),
      title: form.title,
      author: form.author,
      notes: form.notes,
      status: "reading",
      addedAt: new Date().toISOString(),
    };
    books.push(book);
    await saveBooks(books);
    redirect(res, `/books/${book.id}`);
    return;
  }

  const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
  if (method === "POST" && finishMatch) {
    const id = decodeURIComponent(finishMatch[1]);
    const books = await loadBooks();
    const book = books.find((b) => b.id === id);
    if (!book) {
      send(res, 404, layout("Not found", "<h1>Book not found</h1><p><a href=\"/\">Back</a></p>"));
      return;
    }
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
    redirect(res, `/books/${book.id}`);
    return;
  }

  const bookMatch = path.match(/^\/books\/([^/]+)$/);
  if (method === "GET" && bookMatch) {
    const id = decodeURIComponent(bookMatch[1]);
    const book = (await loadBooks()).find((b) => b.id === id);
    if (!book) {
      send(res, 404, layout("Not found", "<h1>Book not found</h1><p><a href=\"/\">Back</a></p>"));
      return;
    }
    send(res, 200, bookPage(book));
    return;
  }

  if (method === "GET" && path === "/style.css") {
    try {
      const css = await readFile(join(PUBLIC_DIR, "style.css"));
      send(res, 200, css, MIME[".css"]);
    } catch {
      send(res, 404, "Not found", "text/plain; charset=utf-8");
    }
    return;
  }

  send(res, 404, layout("Not found", "<h1>Not found</h1><p><a href=\"/\">Back</a></p>"));
}

const server = createServer((req, res) => {
  handleRequest(req, res).catch((err) => {
    console.error(err);
    if (!res.headersSent) send(res, 500, "Something went wrong.", "text/plain; charset=utf-8");
    else res.end();
  });
});

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  server.listen(PORT, () => {
    console.log(`Reading list at http://localhost:${PORT}`);
  });
}

